"""Editorial definitions. Names are study vocabulary, not official community terminology."""
# name | construction | compositional use | boundary / failure mode
TEXT = {
'pivot-locked-landing': ('Pivot-locked target', 'Keep note local x close to zero while rotating the carrier. The incoming notes can orbit dramatically, but their scheduled targets remain at the pivot.', 'Decouples a rotational entrance from a stable hit station.', 'This requires no compensating local-x animation. It is a special geometric invariant of zero lateral offset, distinct from solving moving-target compensation.'),
'side-entry': ('Sideways feed', 'Hold the carrier close to vertical. Scroll along its normal; choose above/below to choose the incoming side. Local note x becomes vertical placement.', 'Makes a phrase enter from a side while preserving independent hit times.', 'Rotation alone does not determine velocity: carrier translation and speed sign also contribute. A mirrored side needs its own landing calculation.'),
'diagonal-entry': ('Oblique feed', 'Keep a tilted carrier stable through the visible approach. The normal supplies the diagonal trajectory; local x separates parallel tracks.', 'Changes the directional accent without introducing curvature.', 'This is straight motion in a rotated coordinate system. Do not describe it as a curved fall.'),
'rising-entry': ('Upward feed', 'Invert the approach normal using a 180-degree carrier or below-side notes. Keep the landing visible while distance decreases.', 'Creates an inverted reading direction or a response to descending notes.', 'An upside-down note sprite is not sufficient evidence. This detector uses the actual approach displacement.'),
'turning-approach': ('Quarter-turn arc', 'Rotate the carrier during the note lifetime. Both the lateral offset and remaining scroll distance rotate around the carrier pivot.', 'Bends the incoming route into an arc before contact.', 'A constant angular rate does not produce a circular note path because scroll radius is shrinking. Protect the whole incoming lifetime.'),
'half-turn-hook': ('Half-turn hook', 'Give the carrier roughly a half turn during approach, then let the remaining distance close to zero at the scheduled hit.', 'Produces a hooked route with a strongly changed final approach axis.', 'A rotation discontinuity is a teleport, not a smooth hook. Selected examples reject large per-frame jumps.'),
'spinning-approach': ('Spiral delivery', 'Accumulate a large unwrapped rotation while scroll distance decreases. The shrinking radius and angular motion combine into a spiral-like delivery.', 'Turns a sustained approach into an orbital flourish.', 'The locus need not be an exact logarithmic or Archimedean spiral. Offscreen intervals and cover must be checked.'),
'pendulum-approach': ('Pendulum delivery', 'Reverse the rotation channel repeatedly while the note continues to approach. The normal swings side to side.', 'Creates a swaying arrival instead of a fixed oblique feed.', 'Repeated endpoints do not establish a sinusoidal easing function; the source stores piecewise-linear event samples.'),
'lateral-carriage': ('Sliding note carriage', 'Translate carrier x while preserving its angle. All attached notes inherit the same screen translation in addition to normal scroll.', 'Adds a side drift or cross-screen slide to an otherwise ordinary approach.', 'Every visible note on the carrier moves, including later notes. It is not a per-note x animation.'),
'elevator-approach': ('Elevator delivery', 'Move the carrier vertically while notes scroll toward it. Compare the carrier velocity with the scrolling velocity.', 'Can compress the approach, chase falling notes, or move the destination away from them.', 'Moving a destination and changing scroll speed can look similar at one instant but produce different landing positions.'),
'diagonal-carriage': ('Diagonal conveyor', 'Animate both carrier translation channels while holding the orientation nearly constant. The complete note field translates diagonally.', 'Moves a phrase between screen regions as one unit.', 'The pivot path is diagonal; the resulting note path also contains scroll and need not have the same angle.'),
'serpentine-carriage': ('Serpentine carriage', 'Alternate the carrier x direction during approach. Normal scroll supplies progression while shared x oscillation supplies the bends.', 'Makes a note or stream weave across the screen.', 'This is genuine lateral motion of individual notes. It differs from a static zigzag formation of individually straight notes.'),
'moving-pivot-hook': ('Travelling-pivot curve', 'Combine translation and rotation of the carrier over the same interval. Solve the final pivot and angle from the intended landing.', 'Creates asymmetric hooks and swept curves that a fixed pivot cannot reproduce.', 'Translation and rotation are non-interchangeable transforms. Reusing only their ranges loses the path and timing relationship.'),
'stop-and-release': ('Suspended scroll release', 'Insert a zero-speed plateau, then restore positive scrolling. Carrier motion may continue while normal distance is frozen.', 'Separates a suspended visual preparation from a later release.', 'Zero scroll is not necessarily zero screen velocity. Notes can keep moving through carrier translation or rotation.'),
'reverse-scroll': ('Retreat and return', 'Use a negative-speed interval while a note still lies on the visible side, then return to forward motion before judgment.', 'Temporarily increases the apparent approach distance or folds the route back.', 'Negative speed alone does not prove a visible retreat: cover can hide a note behind its line. The selected trajectory must remain visible.'),
'speed-up-entry': ('Accelerating scroll steps', 'Increase the piecewise-constant speed events during a visible approach. Integrate the events to obtain distance; preserve the note time.', 'Builds urgency in the approach without increasing the number of strikes.', 'Official v3 speed events have a constant value per segment. A smooth-looking ramp is many steps, not an easing field.'),
'braking-entry': ('Braking arrival', 'Reduce the carrier speed during the note approach. Keep the integrated distance and scheduled judgment consistent.', 'Lets a fast entrance relax into a slower readable final approach.', 'Reducing speed can expose future notes much earlier. Inspect subsequent objects as well as the chosen note.'),
'stepped-scroll': ('Pulsed scroll train', 'Sequence multiple materially different speed values during one visible approach. Each segment changes normal velocity, not the judgment timestamp.', 'Gives approach motion a segmented or pulsing texture.', 'Many tiny export segments may merely approximate one smooth curve. Event count alone does not prove multiple designed pulses.'),
'late-fast-entry': ('Late burst arrival', 'Use a high scroll-speed interval so a note traverses the screen in a short visible time. Placement and timing remain separate.', 'Creates a sudden entrance accent.', 'The screening window is only the final contiguous visible approach, not proof that the note was never visible earlier.'),
'invisible-carrier': ('Ghost carriage', 'Set carrier alpha to zero while retaining its transform and speed events. Notes still inherit the moving coordinate frame.', 'Animates notes without displaying the mechanism that transports them.', 'Invisible carrier is an implementation role, not a decorative line. Alpha changes do not make its playable notes fake.'),
'carrier-reveal': ('Revealed delivery rail', 'Animate a carrier while its line changes between invisible and visible states. Time the reveal relative to the note arrival.', 'Allows the line to announce or explain an unusual incoming trajectory.', 'A line fade normally affects the line sprite, not the attached notes. The note lifetime is independent of line visibility.'),
'below-side-transform': ('Reverse-side carriage', 'Place notes below the carrier and animate that carrier. The approach normal is reversed while the lateral coordinate stays attached.', 'Builds inverted or opposing entrances with the same transform channels.', 'Below-side is a local side, not necessarily the bottom of the screen after rotation.'),
'screen-space-foldback': ('Lateral foldback', 'Compose transforms whose resulting note x coordinate reverses direction more than once. Inspect the resultant path, not only source x events.', 'Creates a hook-return or weaving trajectory through transform interference.', 'Screen-space reversals can come from rotation even when carrier x is monotone. Small numerical wiggles are filtered.'),
'settle-before-hit': ('Settled landing', 'Complete a substantial carrier translation before judgment, then keep a short terminal interval nearly stationary.', 'Separates a theatrical entrance from a stable final destination.', 'The selected case proves a terminal pose plateau, not a universal readability benefit or a player-tested settling margin.'),
'transported-hold': ('Transported sustain', 'Move the carrier while a Hold is already active. With the head attached at distance zero, the contact station follows the carrier and its local x.', 'Carries a sustained contact through a spatial phrase.', 'The head path is a contact path. Tail length and appearance need native rendering because official and converted Hold speed semantics can differ.'),
'pivoted-hold': ('Pivoted sustain', 'Rotate a nearly stationary carrier while an active Hold has nonzero lateral offset. Its held station sweeps an arc about the pivot.', 'Turns a sustain into a spatial sweep.', 'A Hold at local x=0 stays at the pivot despite rotation. Check actual contact displacement before calling it a sweeping Hold.'),
'orbiting-hold': ('Travelling sustain orbit', 'Combine carrier translation and rotation during an active Hold. The contact follows the moving pivot plus its rotated lateral offset.', 'Produces compound sustained-contact motion.', 'Do not infer finger feasibility from geometry alone. Entry, occupancy, release, and other simultaneous contacts remain separate constraints.'),
'invisible-hold-guide': ('Invisible sustain guide', 'Hide a moving or rotating Hold carrier. The visible Hold still identifies the evolving contact location.', 'Keeps the sustain motion while removing the accompanying line stroke.', 'Hiding the line does not remove the contact requirement. A zero-offset Hold may remain still even while its carrier rotates.'),
'travelling-hit-station': ('Travelling repeated station', 'Keep a sequence near one local x while the carrier moves. Consecutive scheduled judgments occupy different screen positions.', 'Moves a repeated rhythmic station through the playfield.', 'This describes consecutive landing positions, not necessarily a curved approach of each note or a particular fingering.'),
'compensated-landing': ('Fixed target, moving carrier', 'Counteract carrier motion with different local note x values so multiple scheduled judgments remain in one small screen region.', 'Allows elaborate approach animation around a stable sequence of targets.', 'One x degree of freedom cannot compensate arbitrary two-dimensional motion. The measured cases satisfy the constraint approximately, not for every possible transform.'),
'zigzag-note-formation': ('Zigzag stream silhouette', 'Keep the carrier stable and alternate successive local note x positions. At one instant the time-ordered notes form a zigzag.', 'Draws a jagged ribbon using placement rather than per-note lateral animation.', 'Each individual note can still move perfectly straight. Do not confuse the formation with serpentine carriage.'),
'arched-note-formation': ('Arched stream silhouette', 'On a stable carrier, vary local x across successive note times with one broad reversal. Their simultaneous arrangement bends into an arch or lobe.', 'Creates a curved mass of notes while retaining simple individual approach.', 'One reversal establishes an arch-like contour, not an exact circle, sine wave, or musical phrase boundary.'),
'speed-fanned-formation': ('Differential-speed silhouette', 'Assign different note speed multipliers to notes on a stable carrier. Remaining distances scale differently, changing the visible formation.', 'Spreads or compresses rows and bends the silhouette without moving the carrier.', 'Per-note speed changes approach distance, not the note timestamp. This formation may combine with nonuniform note spacing.'),
'opposed-approach-chord': ('Opposing entrances', 'Place simultaneous notes on independent carriers whose measured approach vectors point substantially against each other.', 'Creates a collision-like or call-and-response arrival at one timestamp.', 'Opposing entrances may land far apart; they are not automatically a collision at the same target.'),
'orthogonal-approach-chord': ('Right-angle entrances', 'Use independent carriers to make simultaneous notes arrive along approximately perpendicular screen-space vectors.', 'Combines a vertical reading direction with a lateral response.', 'The measured vector is a short approach chord. Curved paths can have a different instantaneous final velocity.'),
'converging-to-one-station': ('Convergent target', 'Start simultaneous notes in separated regions and transform their carriers toward nearly coincident landing positions.', 'Creates a visual gathering point.', 'Several overlapping playable objects are still several objects. Shared judgment behavior and difficulty are not inferred from coincident centers.'),
'splitting-from-one-region': ('Split delivery', 'Start simultaneous incoming notes in one small region, then use distinct carrier transforms to deliver them to separated targets.', 'Turns one visible cluster into a spread of landing stations.', 'Close sampled starting positions do not prove the objects were born together. Review the earlier lifetime if recreating the entrance.'),
'differential-speed-chord': ('Unequal-depth chord', 'Give simultaneous notes parallel incoming directions but substantially different traversed distances through carrier or note speed differences.', 'Makes one strike group occupy multiple apparent depths.', 'This is not a timing offset. All selected heads share a timestamp to the chord-grouping precision.'),
'visible-anchor-hidden-partner': ('Visible rail with ghost partner', 'Keep one simultaneous carrier visible and another hidden. Their independent transforms give the partner its own incoming route.', 'Retains a visible reference while adding a less literal note entrance.', 'The visible rail is not necessarily the hidden notes\' physical judgment line; compare actual landing coordinates.'),
'horizontal-sweep': ('Horizontal line wipe', 'Translate a visible note-free carrier horizontally with enough perpendicular displacement to move its stroke across the viewport.', 'Creates a side-to-side background wipe.', 'Sliding an infinite horizontal line along its own direction changes no visible geometry. These selected cases require normal displacement.'),
'vertical-sweep': ('Vertical line wipe', 'Translate a visible note-free carrier vertically while its orientation stays nearly fixed.', 'Moves a horizon or scan line through the stage.', 'Position channels are pivot coordinates. A vertical line translated vertically can be visually unchanged; normal displacement is checked.'),
'diagonal-sweep': ('Diagonal line wipe', 'Translate a note-free carrier in both axes while holding its angle. Use the component perpendicular to the stroke to control the visible wipe.', 'Moves a geometric boundary diagonally through the scene.', 'Tangential pivot movement is not equivalent to visible stroke movement. The viewer shows both the pivot and resulting stroke.'),
'fixed-pivot-rotation': ('Hinged blade', 'Keep a note-free carrier origin almost fixed and animate rotation. The line sweeps through the screen about that pivot.', 'Creates a hinge, clock-hand, or sweeping blade gesture.', 'A line repeats its visible orientation every 180 degrees, even though its attached coordinate frame would need 360 degrees.'),
'travelling-blade': ('Travelling blade', 'Animate both the origin and angle of a visible note-free line. Translation relocates the hinge while rotation changes the stroke.', 'Produces asymmetric slices and drifting rotational accents.', 'Large numerical origin motion may be mostly tangential or offscreen. Judge the clipped visible stroke, not raw x/y range alone.'),
'lateral-shuttle': ('Lateral shuttle', 'Reverse the x translation of a note-free line several times. Keep a visible normal component so the reversals move the stroke.', 'Creates a repeated sweeping background gesture.', 'The detector identifies direction reversals, not an exact sinusoidal oscillator or tempo-synchronized pulse.'),
'vertical-bounce': ('Vertical shuttle', 'Reverse the y translation of a note-free line repeatedly while controlling its visible orientation and alpha.', 'Creates bouncing horizons or repeated vertical sweeps.', 'A bounce name describes the path shape; no gravity or physical simulation exists in the chart.'),
'rocking-line': ('Rocking blade', 'Alternate the rotation direction of a visible empty carrier. Keep its pivot fixed or add a secondary translation.', 'Makes a pendulum-like or agitated background gesture.', 'Unwrapped angle motion matters. A 179 to -179 raw interpolation can be a large turn rather than the intended short wrap.'),
'windmill': ('Continuous windmill', 'Accumulate at least roughly one full turn over the observed window while the empty line stays visible.', 'Creates sustained rotational activity.', 'A single line is geometrically repeated every half turn. Multiple overlapping lines can amplify brightness without adding distinct rays.'),
'fade-in-motion': ('Emerging stroke', 'Raise alpha while a note-free carrier is translating or rotating. The reveal and movement channels are timed independently.', 'Lets a stage element arrive gradually during a motion.', 'Opacity only changes the stroke visibility. Counting the alpha and movement exports as separate motifs would double-count one construction.'),
'fade-out-motion': ('Dissolving stroke', 'Lower alpha while continuing a note-free carrier motion, then reposition it while hidden if the next phrase needs reuse.', 'Lets an element leave without a hard disappearance.', 'A fade-out window may be only one part of a longer pulse. Inspect the entry and next reuse.'),
'strobe-line': ('Strobing stroke', 'Cross the visibility threshold repeatedly using alpha events, with motion optional. Spatial motion turns repeated flashes into separated positions.', 'Creates a flickering accent or sampled trail-like impression.', 'This is one stroke shown at different times, not simultaneous cloned trails. Very short pulses may be missed by coarse sampling.'),
'single-flash': ('Flashed stroke', 'Reveal and hide a line within a bounded interval. Pose can be static or animated during the flash.', 'Adds a brief background punctuation.', 'A selected window with two threshold crossings is a local flash; it does not prove only one flash exists in the full song.'),
'breathing-line': ('Opacity breathing', 'Vary alpha without fully hiding the note-free line. Retain its geometry or combine the envelope with another motion.', 'Changes visual weight while maintaining continuity.', 'Alpha beyond the display range is clamped in the explanatory player. Negative alpha conventions are not treated as ordinary fades.'),
'offscreen-pivot-wipe': ('Remote-pivot sweep', 'Place the carrier pivot outside the viewport but let its extended stroke intersect the screen. Moving or rotating that remote pivot sweeps the visible segment.', 'Creates broad sweeps whose hinge is not visible.', 'An offscreen pivot does not mean the line is offscreen. Finite native sprite length remains a renderer-dependent limit.'),
'parallel-opening': ('Opening parallel gate', 'Keep two empty carriers parallel and increase their perpendicular separation. Independent alpha can control entry and exit.', 'Opens a corridor or expands the background stage.', 'Separation must be measured normal to the lines. Distance between their pivots can change without the visible corridor changing.'),
'parallel-closing': ('Closing parallel gate', 'Keep two empty carriers parallel and reduce their perpendicular separation over the passage.', 'Compresses the scene toward a narrow corridor.', 'A collapse need not reach contact or zero width. The card reports the measured start and end gaps.'),
'rotating-rails': ('Rotating parallel rails', 'Give two separated empty carriers nearly identical rotation channels so their strokes remain parallel while the pair turns.', 'Rotates a corridor or double-stripe motif.', 'Matching angles alone is insufficient for rigid rotation: pivot translations determine whether spacing is preserved.'),
'breathing-corridor': ('Breathing corridor', 'Oscillate the normal separation of two parallel empty lines. Their joint translation can move the corridor while its width changes.', 'Makes an opening/closing background rhythm.', 'Do not replace normal separation with raw x difference when the corridor rotates.'),
'parallel-conveyor': ('Parallel translation field', 'Translate two separated parallel lines together while holding their perpendicular separation nearly constant.', 'Moves a persistent stripe structure across the stage.', 'A matched separation at the endpoints does not prove constant width; the detector checks the sampled interval.'),
'hinged-fan': ('Opening hinge fan', 'Use nearly coincident origins with distinct rotations. Change the angular separation of two visible empty lines.', 'Opens or closes a wedge around a shared hinge.', 'Two infinite lines create four sectors, not a filled fan. Any impression of a filled wedge comes from other content.'),
'counter-rotating-cross': ('Counter-rotating cross', 'Rotate two nearly co-pivoted empty lines in opposite directions during the same interval.', 'Produces an interlocking rotational crossing.', 'Opposite net rotations can contain additional reversals. The pose trace and source events reveal the full motion.'),
'scissor-crossing': ('Scissor crossing', 'Move two line orientations from nearly parallel to a substantially crossed angle, or the reverse.', 'Transitions between rails and an X-like background.', 'The lines need not share a pivot; their intersection may migrate or leave the viewport.'),
'moving-line-comb': ('Moving stripe comb', 'Use at least three visible, distinctly separated, approximately parallel empty lines, then translate or rotate the set.', 'Builds a multi-stripe stage field.', 'Distinct pivot positions are not sufficient: strokes must have distinct normal offsets. Near-duplicates are collapsed for counting.'),
'radial-line-fan': ('Radial spoke field', 'Place at least three distinct line orientations around a common pivot. Animate their angles, position, or visibility as a group.', 'Creates a starburst-like or radial stage geometry.', 'Every full line contributes two opposite rays. This is not necessarily a regular polygon, circular outline, or physical perspective grid.'),
}

def vocabulary():
    return {k:dict(name=v[0],construction=v[1],use=v[2],boundary=v[3]) for k,v in TEXT.items()}
